package notification.orchestration;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import notification.core.NotificationContext;import notification.routing.ChannelHandler;import notification.routing.ChannelRouter;import org.springframework.stereotype.Service;/** * Delegates to the ChannelHandler for the given type. * TODO: add pre/post hooks, metrics, retry envelope. */@Slf4j@Service@RequiredArgsConstructorpublic class DefaultNotificationOrchestrator implements NotificationOrchestrator {    private final ChannelRouter router;    @Override    public void orchestrate(NotificationContext ctx) {        ChannelHandler handler = router.route(ctx.getType());        if (handler == null) {            log.warn("[orchestrator] no handler for type={}", ctx.getType());            return;        }        handler.handle(ctx);    }}